    s = unicodedata.normalize('NFD', s)
    s = ''.join(ch for ch in s if not unicodedata.combining(ch))
    # Replace any non-alphanumeric char with a hyphen, then collapse runs
    out = []
    for ch in s:
        if ch.isalnum():
            out.append(ch)
        else:
            out.append('-')
    parts = [p for p in ''.join(out).split('-') if p]
    return '-'.join(parts)

